193:     private async Task WarmupAsync(int maxLines, CancellationToken cancellationToken)
194:     {
195:         try
196:         {
197:             var document = _getUserDocument();
198:             if (document == null) return;
199: 
200:             // 先触发一次完整 SemanticModel 构建（首次几百 ms），确保后续逐行分类拿到语义结果
201:             // （否则前几行可能因模型未就绪只回语法分类）。语义分类用 document.GetSemanticModelAsync。
202:             try
203:             {
204:                 await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(false);
205:             }
206:             catch { /* 构建失败则预热退化为普通分类，不阻塞 */ }
207:             if (cancellationToken.IsCancellationRequested) return;
208: 
209:             var lineCount = Math.Min(maxLines, _document.LineCount);
210:             for (int lineNumber = 1; lineNumber <= lineCount; lineNumber++)
211:             {
212:                 if (cancellationToken.IsCancellationRequested) return;
213:                 var documentLine = _document.GetLineByNumber(lineNumber);
214:                 if (documentLine.TotalLength == 0) continue;
215: 
216:                 IEnumerable<ClassifiedSpan> spans;
217:                 try
218:                 {
219:                     spans = await GetClassifiedSpansAsync(document, documentLine).ConfigureAwait(false);
220:                 }
221:                 catch { continue; }
222: 
223:                 var highlightedLine = new HighlightedLine(_document, documentLine);
224:                 foreach (var classifiedSpan in spans)
225:                 {
226:                     if (IsOutsideLine(classifiedSpan, documentLine)) continue;
227:                     highlightedLine.Sections.Add(new HighlightedSection
228:                     {
229:                         Color = _highlightColors.GetBrush(classifiedSpan.ClassificationType),
230:                         Offset = classifiedSpan.TextSpan.Start,
231:                         Length = classifiedSpan.TextSpan.Length,
232:                     });
233:                 }
234: 
235:                 // 写 _cachedLines（行进入可视区时 HighlightLine 命中直接复用）
236:                 if (_document.Version != null)
237:                 {
238:                     _cachedLines.Add(new CachedLine(highlightedLine, _document.Version));
239:                     if (_cachedLines.Count > CacheSize)
240:                         _cachedLines.RemoveRange(0, CacheSize / 2);
241:                 }
242:             }
243: 
244:             // 预热完成触发重绘（AvalonEdit 对受影响行重画，命中缓存显示分类色）
245:             HighlightingStateChanged?.Invoke(1, lineCount);
246:             _warmupTcs.TrySetResult();
247:         }
248:         catch { /* 预热失败不阻塞主流程 */ }
249:         finally
250:         {
251:             // 无论是否成功，都置位预热完成信号（避免等待方永久挂起）
252:             _warmupTcs.TrySetResult();
253:         }
254:     }
